package com.example.g.viewmodels;
import android.app.Application;import androidx.annotation.NonNull;import androidx.lifecycle.*;import com.example.g.models.MediaItem;import com.example.g.repositories.MediaRepository;import java.util.*;
public class PhotosViewModel extends AndroidViewModel {private final MutableLiveData<List<MediaItem>> media=new MutableLiveData<>(Collections.emptyList());private final MutableLiveData<Boolean> loading=new MutableLiveData<>(false);private final MutableLiveData<String> error=new MutableLiveData<>();public PhotosViewModel(@NonNull Application a){super(a);}public LiveData<List<MediaItem>> media(){return media;}public LiveData<Boolean> loading(){return loading;}public LiveData<String> error(){return error;}public void refresh(){if(Boolean.TRUE.equals(loading.getValue()))return;loading.setValue(true);error.setValue(null);MediaRepository.get(getApplication()).load(5000,0,(items,e)->{media.setValue(items);error.setValue(e==null?null:(e.getMessage()==null?"Unable to load device media":e.getMessage()));loading.setValue(false);});}}
